// リクエストボディの厳格な検証・サニタイズ（OSコマンドインジェクション防止）
const fs = require('fs');
const body = $input.first().json.body || $input.first().json;

if (!body.product_name || typeof body.product_name !== 'string') {
  throw new Error('product_name is required and must be a string');
}

// 安全なスラグへの正規化（英数字・アンダースコア・ハイフンのみ許可）
const safeSlug = body.product_name.replace(/[^a-zA-Z0-9_-]/g, '_').substring(0, 50) || 'campaign';

// プロバイダー・数値パラメータのホワイトリスト検証
const allowedProviders = ['auto', 'gemini', 'mock'];
const provider = allowedProviders.includes(body.provider) ? body.provider : 'auto';
const variantsCount = Math.min(Math.max(parseInt(body.variants) || 3, 1), 5);

// 一時ブリーフファイルの安全な書き出し
const briefFilePath = `/tmp/brief_${safeSlug}.json`;
fs.writeFileSync(briefFilePath, JSON.stringify(body, null, 2), 'utf-8');

return [{
  json: {
    product_name: body.product_name,
    safe_slug: safeSlug,
    brief_path: briefFilePath,
    variants_count: variantsCount,
    provider: provider
  }
}];
